/bin/bash -lc "mkdir -p codex_stage && python - <<'PY'
import csv, os
src='inputs/count.csv'
outdir='codex_stage'
with open(src, newline='') as f:
    r=csv.DictReader(f)
    samples=[h for h in r.fieldnames if h"'!='"'geneID']
    handles={s: open(os.path.join(outdir, f'{s}.tsv'), 'w', newline='') for s in samples}
    writers={s: csv.writer(handles[s], delimiter='\\t') for s in samples}
    for s in samples:
        writers[s].writerow(['geneID', s])
    for row in r:
        for s in samples:
            writers[s].writerow([row['geneID'], row[s]])
    for h in handles.values():
        h.close()
print(samples)
PY
